import { expect, test } from 'vitest'
import { userEvent } from 'vitest/browser'

// Temporary plain-native comparison; no Field and no fieldset inside a legend.
test('diagnostic native nested fieldset inheritance', async () => {
  const container = document.createElement('div')
  container.innerHTML = `<form><button id="before" type="button">Before</button>
    <fieldset id="outer" disabled><legend>Outer first <input id="outer-first" name="outer-first" value="yes"></legend>
    <input id="outer-body" name="outer-body" value="no">
    <fieldset disabled><legend>Inner first <input id="inner-first" name="inner-first" value="no"></legend>
    <input id="inner-body" name="inner-body" value="no"></fieldset></fieldset>
    <button id="after" type="button">After</button></form>`
  document.body.append(container)
  try {
    const outer = container.querySelector<HTMLFieldSetElement>('#outer')!
    const before = container.querySelector<HTMLButtonElement>('#before')!
    const snapshots = []
    for (const disabled of [true, false, true]) {
      outer.disabled = disabled
      const controls = [...container.querySelectorAll<HTMLInputElement>('input')].map((input) => {
        before.focus()
        input.focus()
        let matcherDisabled = true
        try {
          expect(input).toBeDisabled()
        } catch {
          matcherDisabled = false
        }
        return {
          id: input.id,
          ownDisabled: input.hasAttribute('disabled'),
          selectorDisabled: input.matches(':disabled'),
          matcherDisabled,
          focused: document.activeElement === input,
          willValidate: input.willValidate,
        }
      })
      snapshots.push({
        outerDisabled: disabled,
        controls,
        formData: [...new FormData(container.querySelector<HTMLFormElement>('form')!).keys()],
      })
    }
    outer.disabled = true
    before.focus()
    const tabOrder = []
    for (let i = 0; i < 4; i++) {
      await userEvent.keyboard('{Tab}')
      tabOrder.push(document.activeElement?.id || document.activeElement?.tagName)
    }
    throw new Error('[fieldset-native-diagnostic] ' + JSON.stringify({ snapshots, tabOrder }))
  } finally {
    container.remove()
  }
})

